}

Method.Source:
/// <summary>
/// PaffH 20.11.24
/// </summary>
/// <param name = "_nDXPictureManagement">NDXPictureManagement</param>
public static void initValueProdIdent(NDXPictureManagement _nDXPictureManagement)
{
    _nDXPictureManagement.RefTableId = tableNum(NDXProdIdentProcedureTable);
}

/// <summary>
/// PaffH 20.11.24
/// </summary>
/// <param name = "_refTableId">RefTableId</param>
/// <param name = "_pictureType">NDXPictureType</param>
/// <param name = "_dataAreaId">dataAreaId</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXPictureManagement</returns>
public static NDXPictureManagement find(RefTableId _refTableId, NDXPictureType _pictureType, dataAreaId _dataAreaId, boolean _forUpdate = true)
{
    NDXPictureManagement nDXPictureManagement;
    nDXPictureManagement.selectForUpdate(_forUpdate);
    select firstonly nDXPictureManagement
            where nDXPictureManagement.RefTableId == _refTableId
            && nDXPictureManagement.PictureType == _pictureType
            && nDXPictureManagement.DataAreaIdFor == _dataAreaId;
    if (_dataAreaId != '' && nDXPictureManagement.RecId == 0)
    {
        select firstonly nDXPictureManagement
            where nDXPictureManagement.RefTableId == _refTableId
            && nDXPictureManagement.PictureType == _pictureType
            && nDXPictureManagement.DataAreaIdFor == '';
    }
    return nDXPictureManagement;
}

    /// <summary>
    /// PaffH 20.11.24
    /// </summary>
    /// <param name = "_pictureType">NDXPictureType</param>
    /// <param name = "_dataAreaId">dataAreaId</param>
    /// <param name = "_forUpdate">boolean</param>
    /// <returns>NDXPictureManagement</returns>
public static NDXPictureManagement findProdIdent(NDXPictureType _pictureType, dataAreaId _dataAreaId, boolean _forUpdate = true)
    {
        return NDXPictureManagement::find(tableNum(NDXProdIdentProcedureTable), _pictureType, _dataAreaId, _forUpdate);
    }
